// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import {IWasmd} from "./precompiles/IWasmd.sol";
import {IJson} from "./precompiles/IJson.sol";
import {IAddr} from "./precompiles/IAddr.sol";

contract CW20ERC20Pointer is ERC20 {

    address constant WASMD_PRECOMPILE_ADDRESS = 0x0000000000000000000000000000000000001002;
    address constant JSON_PRECOMPILE_ADDRESS = 0x0000000000000000000000000000000000001003;
    address constant ADDR_PRECOMPILE_ADDRESS = 0x0000000000000000000000000000000000001004;

    string public Cw20Address;
    IWasmd public WasmdPrecompile;
    IJson public JsonPrecompile;
    IAddr public AddrPrecompile;

    constructor(string memory Cw20Address_, string memory name_, string memory symbol_) ERC20(name_, symbol_) {
        WasmdPrecompile = IWasmd(WASMD_PRECOMPILE_ADDRESS);
        JsonPrecompile = IJson(JSON_PRECOMPILE_ADDRESS);
        AddrPrecompile = IAddr(ADDR_PRECOMPILE_ADDRESS);
        Cw20Address = Cw20Address_;
    }

    // Queries
    function decimals() public view override returns (uint8) {
        string memory req = _curlyBrace(_formatPayload("token_info", "{}"));
        bytes memory response = WasmdPrecompile.query(Cw20Address, bytes(req));
        return uint8(JsonPrecompile.extractAsUint256(response, "decimals"));
    }

    function balanceOf(address owner) public view override returns (uint256) {
        require(owner != address(0), "ERC20: balance query for the zero address");
        string memory ownerAddr = _formatPayload("address", _doubleQuotes(AddrPrecompile.getSeiAddr(owner)));
        string memory req = _curlyBrace(_formatPayload("balance", _curlyBrace(ownerAddr)));
        bytes memory response = WasmdPrecompile.query(Cw20Address, bytes(req));
        return JsonPrecompile.extractAsUint256(response, "balance");
    }

    function totalSupply() public view override returns (uint256) {
        string memory req = _curlyBrace(_formatPayload("token_info", "{}"));
        bytes memory response = WasmdPrecompile.query(Cw20Address, bytes(req));
        return JsonPrecompile.extractAsUint256(response, "total_supply");
    }

    function allowance(address owner, address spender) public view override returns (uint256) {
        string memory o = _formatPayload("owner", _doubleQuotes(AddrPrecompile.getSeiAddr(owner)));
        string memory s = _formatPayload("spender", _doubleQuotes(AddrPrecompile.getSeiAddr(spender)));
        string memory req = _curlyBrace(_formatPayload("allowance", _curlyBrace(_join(o, s, ","))));
        bytes memory response = WasmdPrecompile.query(Cw20Address, bytes(req));
        return JsonPrecompile.extractAsUint256(response, "allowance");
    }

    // Transactions
    function approve(address spender, uint256 amount) public override returns (bool) {
        // if amount is larger uint128 then set amount to uint128 max
        if (amount > type(uint128).max) {
            amount = type(uint128).max;
        }
        uint256 currentAllowance = allowance(msg.sender, spender);
        if (currentAllowance > amount) {
            string memory spenderAddr = _formatPayload("spender", _doubleQuotes(AddrPrecompile.getSeiAddr(spender)));
            string memory amt = _formatPayload("amount", _doubleQuotes(Strings.toString(currentAllowance - amount)));
            string memory req = _curlyBrace(_formatPayload("decrease_allowance", _curlyBrace(_join(spenderAddr, amt, ","))));
            _execute(bytes(req));
        } else if (currentAllowance < amount) {
            string memory spenderAddr = _formatPayload("spender", _doubleQuotes(AddrPrecompile.getSeiAddr(spender)));
            string memory amt = _formatPayload("amount", _doubleQuotes(Strings.toString(amount - currentAllowance)));
            string memory req = _curlyBrace(_formatPayload("increase_allowance", _curlyBrace(_join(spenderAddr, amt, ","))));
            _execute(bytes(req));
        }
        return true;
    }

    function transfer(address to, uint256 amount) public override returns (bool) {
        require(to != address(0), "ERC20: transfer to the zero address");
        string memory recipient = _formatPayload("recipient", _doubleQuotes(AddrPrecompile.getSeiAddr(to)));
        string memory amt = _formatPayload("amount", _doubleQuotes(Strings.toString(amount)));
        string memory req = _curlyBrace(_formatPayload("transfer", _curlyBrace(_join(recipient, amt, ","))));
        _execute(bytes(req));
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public override returns (bool) {
        require(to != address(0), "ERC20: transfer to the zero address");
        string memory sender = _formatPayload("owner", _doubleQuotes(AddrPrecompile.getSeiAddr(from)));
        string memory recipient = _formatPayload("recipient", _doubleQuotes(AddrPrecompile.getSeiAddr(to)));
        string memory amt = _formatPayload("amount", _doubleQuotes(Strings.toString(amount)));
        string memory req = _curlyBrace(_formatPayload("transfer_from", _curlyBrace(_join(_join(sender, recipient, ","), amt, ","))));
        _execute(bytes(req));
        return true;
    }

    function _execute(bytes memory req) internal returns (bytes memory) {
        (bool success, bytes memory ret) = WASMD_PRECOMPILE_ADDRESS.delegatecall(
            abi.encodeWithSignature(
                "execute(string,bytes,bytes)",
                Cw20Address,
                bytes(req),
                bytes("[]")
            )
        );
        require(success, "CosmWasm execute failed");
        return ret;
    }

    function _formatPayload(string memory key, string memory value) internal pure returns (string memory) {
        return _join(_doubleQuotes(key), value, ":");
    }

    function _curlyBrace(string memory s) internal pure returns (string memory) {
        return string.concat("{", string.concat(s, "}"));
    }

    function _doubleQuotes(string memory s) internal pure returns (string memory) {
        return string.concat("\"", string.concat(s, "\""));
    }

    function _join(string memory a, string memory b, string memory separator) internal pure returns (string memory) {
        return string.concat(a, string.concat(separator, b));
    }
}

contracts/CW721ERC721Pointer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.12;

import "@openzeppelin/contracts/token/common/ERC2981.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import {IWasmd} from "./precompiles/IWasmd.sol";
import {IJson} from "./precompiles/IJson.sol";
import {IAddr} from "./precompiles/IAddr.sol";

contract CW721ERC721Pointer is ERC721,ERC2981 {

    address constant WASMD_PRECOMPILE_ADDRESS = 0x0000000000000000000000000000000000001002;
    address constant JSON_PRECOMPILE_ADDRESS = 0x0000000000000000000000000000000000001003;
    address constant ADDR_PRECOMPILE_ADDRESS = 0x0000000000000000000000000000000000001004;

    string public Cw721Address;
    IWasmd public WasmdPrecompile;
    IJson public JsonPrecompile;
    IAddr public AddrPrecompile;

    error NotImplementedOnCosmwasmContract(string method);
    error NotImplemented(string method);

    constructor(string memory Cw721Address_, string memory name_, string memory symbol_) ERC721(name_, symbol_) {
        WasmdPrecompile = IWasmd(WASMD_PRECOMPILE_ADDRESS);
        JsonPrecompile = IJson(JSON_PRECOMPILE_ADDRESS);
        AddrPrecompile = IAddr(ADDR_PRECOMPILE_ADDRESS);
        Cw721Address = Cw721Address_;
    }

    function supportsInterface(bytes4 interfaceId) public pure override(ERC721, ERC2981) returns (bool) {
        return
            interfaceId == type(IERC2981).interfaceId ||
            interfaceId == type(IERC165).interfaceId ||
            interfaceId == type(IERC721).interfaceId ||
            interfaceId == type(IERC721Metadata).interfaceId;
    }

    // Queries
    // owner of the entire collection, not specific to a token id
    function owner() public view returns (address) {
        string memory req = _curlyBrace(_formatPayload("ownership", "{}"));
        bytes memory response = WasmdPrecompile.query(Cw721Address, bytes(req));
        bytes memory owner_bytes = JsonPrecompile.extractAsBytes(response, "owner");
        return AddrPrecompile.getEvmAddr(string(owner_bytes));
    }

    function balanceOf(address owner_) public view override returns (uint256) {
        if (owner_ == address(0)) {
            revert ERC721InvalidOwner(address(0));
        }
        uint256 numTokens = 0;
        string memory startAfter;
        string memory qb = string.concat(
            string.concat("\"limit\":1000,\"owner\":\"", AddrPrecompile.getSeiAddr(owner_)),
            "\""
        );
        bytes32 terminator = keccak256("{\"tokens\":[]}");

        bytes[] memory tokens;
        uint256 tokensLength;
        string memory req = string.concat(string.concat("{\"tokens\":{", qb), "}}");
        bytes memory response = WasmdPrecompile.query(Cw721Address, bytes(req));
        while (keccak256(response) != terminator) {
            tokens = JsonPrecompile.extractAsBytesList(response, "tokens");
            tokensLength = tokens.length;
            numTokens += tokensLength;
            startAfter = string.concat(",\"start_after\":", string(tokens[tokensLength-1]));
            req = string.concat(
                string.concat("{\"tokens\":{", string.concat(qb, startAfter)),
                "}}"
            );
            response = WasmdPrecompile.query(Cw721Address, bytes(req));
        }
        return numTokens;
    }

    function ownerOf(uint256 tokenId) public view override returns (address) {
        string memory tId = _formatPayload("token_id", _doubleQuotes(Strings.toString(tokenId)));
        string memory req = _curlyBrace(_formatPayload("owner_of", _curlyBrace(tId)));
        bytes memory response = WasmdPrecompile.query(Cw721Address, bytes(req));
        bytes memory owner_ = JsonPrecompile.extractAsBytes(response, "owner");
        return AddrPrecompile.getEvmAddr(string(owner_));
    }

    function getApproved(uint256 tokenId) public view override returns (address) {
        string memory tId = _formatPayload("token_id", _doubleQuotes(Strings.toString(tokenId)));
        string memory req = _curlyBrace(_formatPayload("approvals", _curlyBrace(tId)));
        bytes memory response = WasmdPrecompile.query(Cw721Address, bytes(req));
        bytes[] memory approvals = JsonPrecompile.extractAsBytesList(response, "approvals");
        if (approvals.length > 0) {
            bytes memory res = JsonPrecompile.extractAsBytes(approvals[0], "spender");
            return AddrPrecompile.getEvmAddr(string(res));
        }
        return address(0);
    }

    function isApprovedForAll(address owner_, address operator) public view override returns (bool) {
        string memory o = _formatPayload("owner", _doubleQuotes(AddrPrecompile.getSeiAddr(owner_)));
        string memory req = _curlyBrace(_formatPayload("all_operators", _curlyBrace(o)));
        bytes memory response = WasmdPrecompile.query(Cw721Address, bytes(req));
        bytes[] memory approvals = JsonPrecompile.extractAsBytesList(response, "operators");
        for (uint i=0; i<approvals.length; i++) {
            bytes memory op = JsonPrecompile.extractAsBytes(approvals[i], "spender");
            if (AddrPrecompile.getEvmAddr(string(op)) == operator) {
                return true;
            }
        }
        return false;
    }

    // 2981
    function royaltyInfo(uint256 tokenId, uint256 salePrice) public view override returns (address, uint256) {
        bytes memory checkRoyaltyResponse = WasmdPrecompile.query(Cw721Address, bytes("{\"extension\":{\"msg\":{\"check_royalties\":{}}}}"));
        bytes memory isRoyaltyImplemented = JsonPrecompile.extractAsBytes(checkRoyaltyResponse, "royalty_payments");
        if (keccak256(isRoyaltyImplemented) != keccak256("true")) {
            revert NotImplementedOnCosmwasmContract("royalty_info");
        }
        string memory tId = _formatPayload("token_id", _doubleQuotes(Strings.toString(tokenId)));
        string memory sPrice = _formatPayload("sale_price", _doubleQuotes(Strings.toString(salePrice)));
        string memory req = _curlyBrace(_formatPayload("royalty_info", _curlyBrace(_join(tId, sPrice, ","))));
        string memory fullReq = _curlyBrace(_formatPayload("extension", _curlyBrace(_formatPayload("msg", req))));
        bytes memory response = WasmdPrecompile.query(Cw721Address, bytes(fullReq));
        bytes memory addr = JsonPrecompile.extractAsBytes(response, "address");
        uint256 amt = JsonPrecompile.extractAsUint256(response, "royalty_amount");
        if (addr.length == 0) {
            return (address(0), amt);
        }
        return (AddrPrecompile.getEvmAddr(string(addr)), amt);
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        // revert if token isn't owned
        ownerOf(tokenId);
        string memory tId = _formatPayload("token_id", _doubleQuotes(Strings.toString(tokenId)));
        string memory req = _curlyBrace(_formatPayload("nft_info", _curlyBrace(tId)));
        bytes memory response = WasmdPrecompile.query(Cw721Address, bytes(req));
        bytes memory uri = JsonPrecompile.extractAsBytes(response, "token_uri");
        return string(uri);
    }

    // 721-Enumerable
    function totalSupply() public view virtual returns (uint256) {
        bytes memory response = WasmdPrecompile.query(Cw721Address, bytes("{\"num_tokens\":{}}"));
        return JsonPrecompile.extractAsUint256(response, "count");
    }

    function tokenOfOwnerByIndex(address, uint256) public view virtual returns (uint256) {
        revert NotImplemented("tokenOfOwnerByIndex");
    }

    function tokenByIndex(uint256) public view virtual returns (uint256) {
        revert NotImplemented("tokenByIndex");
    }

    // Transactions
    function transferFrom(address from, address to, uint256 tokenId) public override {
        if (to == address(0)) {
            revert ERC721InvalidReceiver(address(0));
        }
        require(from == ownerOf(tokenId), "`from` must be the owner");
        string memory recipient = _formatPayload("recipient", _doubleQuotes(AddrPrecompile.getSeiAddr(to)));
        string memory tId = _formatPayload("token_id", _doubleQuotes(Strings.toString(tokenId)));
        string memory req = _curlyBrace(_formatPayload("transfer_nft", _curlyBrace(_join(recipient, tId, ","))));
        _execute(bytes(req));
    }

    function approve(address approved, uint256 tokenId) public override {
        string memory spender = _formatPayload("spender", _doubleQuotes(AddrPrecompile.getSeiAddr(approved)));
        string memory tId = _formatPayload("token_id", _doubleQuotes(Strings.toString(tokenId)));
        string memory req = _curlyBrace(_formatPayload("approve", _curlyBrace(_join(spender, tId, ","))));
        _execute(bytes(req));
    }

    function setApprovalForAll(address operator, bool approved) public override {
        string memory op = _curlyBrace(_formatPayload("operator", _doubleQuotes(AddrPrecompile.getSeiAddr(operator))));
        if (approved) {
            _execute(bytes(_curlyBrace(_formatPayload("approve_all", op))));
        } else {
            _execute(bytes(_curlyBrace(_formatPayload("revoke_all", op))));
        }
    }

    function _execute(bytes memory req) internal returns (bytes memory) {
        (bool success, bytes memory ret) = WASMD_PRECOMPILE_ADDRESS.delegatecall(
            abi.encodeWithSignature(
                "execute(string,bytes,bytes)",
                Cw721Address,
                bytes(req),
                bytes("[]")
            )
        );
        require(success, "CosmWasm execute failed");
        return ret;
    }

    function _queryContractInfo() internal view virtual returns (string memory, string memory) {
        string memory req = _curlyBrace(_formatPayload("contract_info", "{}"));
        bytes memory response = WasmdPrecompile.query(Cw721Address, bytes(req));
        bytes memory respName = JsonPrecompile.extractAsBytes(response, "name");
        bytes memory respSymbol = JsonPrecompile.extractAsBytes(response, "symbol");
        string memory nameStr = string(respName);
        string memory symbolStr = string(respSymbol);
        return (nameStr, symbolStr);
    }

    function _formatPayload(string memory key, string memory value) internal pure returns (string memory) {
        return _join(_doubleQuotes(key), value, ":");
    }

    function _curlyBrace(string memory s) internal pure returns (string memory) {
        return string.concat("{", string.concat(s, "}"));
    }

    function _doubleQuotes(string memory s) internal pure returns (string memory) {
        return string.concat("\"", string.concat(s, "\""));
    }

    function _join(string memory a, string memory b, string memory separator) internal pure returns (string memory) {
        return string.concat(a, string.concat(separator, b));
    }
}

contracts/Picasso.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

contract Picasso is Initializable, OwnableUpgradeable {
    struct Market {
        mapping(address => uint256[]) predictions;
        address[] participants;                // Used for iteration in calculateWinner
        mapping(address => uint256) leaderboard;
        uint256 lastCalculatedEpoch;
        bool isFinalized;
        string ticker;
        uint256 totalFunds;
    }

    struct LeaderboardResponse {
        address user;
        uint256 score;
    }

    mapping(uint32 => Market) private markets; // Markets mapped by date (YYYYMMDD)
    uint256 public maxEntries;
    uint8 public numPredictions;
    uint256 public constant LEADERBOARD_PERCENTAGE = 10;

    event MarketCreated(uint32 date);
    event PredictionSubmitted(uint32 date, address user, uint256[] predictions);
    event PredictionSubmittedByOwner(uint32 date, address user, uint256[] predictions);
    event ScoresAccumulated(uint32 date, uint256 epoch);
    event MarketFinalized(uint32 date);
    event MaxEntriesUpdated(uint256 newMaxEntries);
    event NumPredictionsUpdated(uint8 newNumPredictions);

    function initialize(uint256 _maxEntries, uint8 _numPredictions) public initializer {
        __Ownable_init(msg.sender);
        maxEntries = _maxEntries;
        numPredictions = _numPredictions;
    }

    // MARK: Modifiers
    modifier validDate(uint32 date) {
        uint256 year = date / 10000;
        uint256 month = (date / 100) % 100;
        uint256 day = date % 100;

        require(year > 2024 && year < 2100, "Year must be between 2025 and 2099");
        require(month >= 1 && month <= 12, "Month must be between 1 and 12");

        if (month == 2) {
            uint256 maxDays = (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) ? 29 : 28;
            require(day >= 1 && day <= maxDays, "Invalid day for February");
        } else if (month == 4 || month == 6 || month == 9 || month == 11) {
            require(day >= 1 && day <= 30, "Invalid day for this month");
        } else {
            require(day >= 1 && day <= 31, "Invalid day for this month");
        }
        _;
    }

    modifier marketExists(uint32 date) {
        require(bytes(markets[date].ticker).length > 0, "Market does not exist for this date.");
        _;
    }

    modifier onlyUniqueParticipant(uint32 date) {
        Market storage market = markets[date];
        require(market.predictions[msg.sender].length == 0, "Duplicate prediction for this market by user.");
        _;
    }

    modifier belowMaxEntries(uint32 date) {
        require(markets[date].participants.length < maxEntries, "Market has reached max entries.");
        _;
    }

    // MARK: ADMIN FUNCTIONS
    function setMaxEntries(uint256 newMaxEntries) external onlyOwner {
        require(newMaxEntries > 0, "Max entries must be greater than zero.");
        maxEntries = newMaxEntries;
        emit MaxEntriesUpdated(newMaxEntries);
    }

    function setNumPredictions(uint8 newNumPredictions) external onlyOwner {
        require(newNumPredictions > 0, "Number of predictions must be greater than zero");
        numPredictions = newNumPredictions;
        emit NumPredictionsUpdated(newNumPredictions);
    }

    function createMarket(uint32 date, string calldata ticker) external onlyOwner validDate(date) {
        require(bytes(ticker).length > 0, "Ticker must not be empty");

        Market storage market = markets[date];
        market.ticker = ticker;

        emit MarketCreated(date);
    }

    // MARK: PUBLIC FUNCTIONS
    function submitPrediction(uint32 date, uint256[] calldata predictions) external payable validDate(date) marketExists(date) onlyUniqueParticipant(date) belowMaxEntries(date) {
        require(msg.value == 2 ether, "You must send exactly 2 SEI to submit a prediction");

        Market storage market = markets[date];

        require(market.predictions[msg.sender].length == 0, "Predictions already submitted");
        require(predictions.length == numPredictions, string(abi.encodePacked("Invalid prediction length; expected ", Strings.toString(numPredictions))));

        market.predictions[msg.sender] = predictions;
        market.participants.push(msg.sender);

        market.totalFunds += msg.value;

        emit PredictionSubmitted(date, msg.sender, predictions);
    }

    function submitPredictionByOwner(uint32 date, address user, uint256[] calldata predictions) external onlyOwner validDate(date) marketExists(date) belowMaxEntries(date) {
        require(predictions.length == numPredictions, string(abi.encodePacked("Invalid prediction length; expected ", Strings.toString(numPredictions))));

        Market storage market = markets[date];

        // Add user to participants if they are not already in the list
        if (market.predictions[user].length == 0) {
            market.participants.push(user);
        }

        // Overwrite or add the prediction
        market.predictions[user] = predictions;

        emit PredictionSubmittedByOwner(date, user, predictions);
    }

    function accumulateScore(uint32 date, uint8 epoch, bool throwerror) external onlyOwner validDate(date) {
        Market storage market = markets[date];
        require(!market.isFinalized, "Market has already been finalized.");
        require(epoch > market.lastCalculatedEpoch, "Epoch already calculated or invalid");
        require(epoch <= numPredictions, "Epoch exceeds number of predictions");

        // Retrieve dummy prices from the mocked Pyth function.
        uint256[] memory pythPrices = getPricesFromPyth(date, epoch, market.ticker, throwerror);

        for (uint256 i = 0; i < market.participants.length; i++) {
            address user = market.participants[i];
            uint256 currentScore = market.leaderboard[user];
            uint256[] memory predictions = market.predictions[user];

            for (uint256 j = market.lastCalculatedEpoch; j < epoch; j++) {
                currentScore += absDifference(predictions[j], pythPrices[j]);
            }

            market.leaderboard[user] = currentScore;
        }

        market.lastCalculatedEpoch = epoch;

        emit ScoresAccumulated(date, epoch);
    }

    function finalizeMarket(uint32 date) external validDate(date) marketExists(date) {
        Market storage market = markets[date];
        require(market.lastCalculatedEpoch == numPredictions, "Not all epochs have been calculated");

        address[] memory sortedLeaderboard = sortLeaderboard(market.leaderboard, market.participants);

        payWinners(date, sortedLeaderboard, market.participants.length);

        market.isFinalized = true;
        market.totalFunds = 0;

        emit MarketFinalized(date);
    }

    // MARK: Helper functions

    /// @notice Dummy implementation to simulate retrieving price points from Pyth.
    /// @dev Returns an array of dummy price points with each price being (index + 1) * 1000.
    function getPricesFromPyth(
        uint32 /*date*/,
        uint8 epoch,
        string memory /*ticker*/,
        bool throwError
    )
    internal
    pure
    returns (uint256[] memory)
    {
        if (throwError) {
            revert("Error triggered as requested");
        }

        uint256[] memory prices = new uint256[](epoch);
        for (uint8 i = 0; i < epoch; i++) {
            prices[i] = (i + 1) * 1000;
        }
        return prices;
    }

    function absDifference(uint256 a, uint256 b) internal pure returns (uint256) {
        return a > b ? a - b : b - a;
    }

    function sortLeaderboard(mapping(address => uint256) storage leaderboard, address[] storage participants) internal view returns (address[] memory){
        uint256 length = participants.length;
        address[] memory sortedParticipants = new address[](length);
        uint256[] memory scores = new uint256[](length);

        // Populate temporary arrays
        for (uint256 i = 0; i < length; i++) {
            sortedParticipants[i] = participants[i];
            scores[i] = leaderboard[participants[i]];
        }

        // Perform a simple bubble sort (can be replaced with more efficient sorts)
        for (uint256 i = 0; i < length; i++) {
            for (uint256 j = 0; j < length - 1; j++) {
                if (scores[j] > scores[j + 1]) {
                    // Swap scores
                    (scores[j], scores[j + 1]) = (scores[j + 1], scores[j]);

                    // Swap participants
                    (sortedParticipants[j], sortedParticipants[j + 1]) = (
                        sortedParticipants[j + 1],
                        sortedParticipants[j]
                    );
                }
            }
        }

        return sortedParticipants;
    }

    function payWinners(uint32 date, address[] memory sortedLeaderboard, uint256 participantCount) internal {
        require(participantCount > 0, "No participants to distribute rewards");

        Market storage market = markets[date];
        uint256 totalFunds = market.totalFunds;
        require(totalFunds > 0, "No funds available for distribution");

        // Calculate distribution amounts
        uint256 winnerReward = (totalFunds * 80) / 100; // 80% to the winner
        uint256 ownerReward = (totalFunds * 10) / 100;  // 10% to the contract owner
        uint256 refundPool = (totalFunds * 10) / 100;   // 10% to top 10%

        // Transfer rewards
        address winner = sortedLeaderboard[0];
        payable(winner).transfer(winnerReward);

        // Transfer owner's share
        payable(owner()).transfer(ownerReward);

        // Refund the top 10% (excluding the winner)
        uint256 refundCount = (participantCount * LEADERBOARD_PERCENTAGE) / 100;
        uint256 refundAmount = refundPool / refundCount;

        for (uint256 i = 1; i <= refundCount; i++) {
            address participant = sortedLeaderboard[i];
            payable(participant).transfer(refundAmount);
        }
    }

    // MARK: Views
    function getParticipants(uint32 date) external view marketExists(date) returns (address[] memory) {
        return markets[date].participants;
    }

    function getUserPrediction(uint32 date, address user) external view marketExists(date) returns (uint256[] memory) {
        return markets[date].predictions[user];
    }

    function getTicker(uint32 date) external view marketExists(date) returns (string memory) {
        return markets[date].ticker;
    }

    function getLeaderboard(uint32 date, uint8 page, uint8 limit) external view marketExists(date) returns (LeaderboardResponse[] memory){
        require(limit > 0, "Limit must be greater than zero");
        require(limit <= 50, "Limit exceeds maximum pagination size");

        uint256 totalParticipants = markets[date].participants.length;
        require(page * limit < totalParticipants, "Invalid page or limit");

        uint256 start = page * limit;
        uint256 end = start + limit > totalParticipants ? totalParticipants : start + limit;
        LeaderboardResponse[] memory responses = new LeaderboardResponse[](end - start);

        for (uint256 i = start; i < end; i++) {
            address user = markets[date].participants[i];
            responses[i - start] = LeaderboardResponse(user, markets[date].leaderboard[user]);
        }

        return responses;
    }
}

