// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/proxy/utils/Initializable.sol";

/**
 * @title SimpleAccount
 * @dev A simple ERC-4337 compatible smart contract wallet
 * @notice This account can be used with the EntryPoint for gasless transactions
 */
contract SimpleAccount is Initializable {
    using ECDSA for bytes32;

    IEntryPoint private immutable _entryPoint;

    address public owner;
    uint256 public nonce;

    event SimpleAccountInitialized(IEntryPoint indexed entryPoint, address indexed owner);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }

    modifier onlyEntryPoint() {
        require(msg.sender == address(_entryPoint), "Only entry point can call this function");
        _;
    }

    constructor(IEntryPoint anEntryPoint) {
        _entryPoint = anEntryPoint;
        _disableInitializers();
    }

    /**
     * @dev Initialize the account with an owner
     * @param anOwner The owner of this account
     */
    function initialize(address anOwner) public virtual initializer {
        _initialize(anOwner);
    }

    function _initialize(address anOwner) internal virtual {
        owner = anOwner;
        emit SimpleAccountInitialized(_entryPoint, anOwner);
    }

    /**
     * @dev Execute a transaction from this account
     * @param dest The destination address
     * @param value The amount of ETH to send
     * @param func The function call data
     */
    function execute(address dest, uint256 value, bytes calldata func) external onlyOwner {
        _call(dest, value, func);
    }

    /**
     * @dev Execute a batch of transactions
     * @param dest The destination addresses
     * @param value The amounts of ETH to send
     * @param func The function call data
     */
    function executeBatch(address[] calldata dest, uint256[] calldata value, bytes[] calldata func) external onlyOwner {
        require(dest.length == func.length && (value.length == 0 || value.length == func.length), "Wrong array lengths");
        if (value.length == 0) {
            for (uint256 i = 0; i < dest.length; i++) {
                _call(dest[i], 0, func[i]);
            }
        } else {
            for (uint256 i = 0; i < dest.length; i++) {
                _call(dest[i], value[i], func[i]);
            }
        }
    }

    /**
     * @dev Validate user operation according to ERC-4337
     * @param userOp The user operation to validate
     * @param userOpHash The hash of the user operation
     * @param missingAccountFunds The amount of funds missing for the account
     */
    function validateUserOp(
        IEntryPoint.UserOperation calldata userOp,
        bytes32 userOpHash,
        uint256 missingAccountFunds
    ) external virtual onlyEntryPoint returns (uint256 validationData) {
        require(userOp.sender == address(this), "Invalid sender");

        // Validate signature (simplified - you'd implement proper ECDSA recovery)
        // For demo purposes, we'll skip signature validation
        // In production, you'd use: address recovered = ecrecover(userOpHash, v, r, s);

        // Validate nonce
        require(userOp.nonce == nonce++, "Invalid nonce");

        // Pay for missing account funds
        if (missingAccountFunds > 0) {
            (bool success, ) = payable(msg.sender).call{value: missingAccountFunds}("");
            require(success, "Failed to pay missing account funds");
        }

        return 0;
    }

    /**
     * @dev Get the entry point
     */
    function entryPoint() public view returns (IEntryPoint) {
        return _entryPoint;
    }

    /**
     * @dev Get the account nonce
     */
    function getNonce() public view returns (uint256) {
        return nonce;
    }

    /**
     * @dev Deposit ETH to this account
     */
    function deposit() public payable {
        entryPoint().depositTo{value: msg.value}(address(this));
    }

    /**
     * @dev Withdraw ETH from this account
     * @param withdrawAddress The address to withdraw to
     * @param amount The amount to withdraw
     */
    function withdrawDepositTo(address payable withdrawAddress, uint256 amount) public onlyOwner {
        entryPoint().withdrawTo(withdrawAddress, amount);
    }

    /**
     * @dev Add stake to the entry point
     * @param unstakeDelay The unstake delay
     */
    function addDeposit(uint256 unstakeDelay) public payable {
        entryPoint().addStake{value: msg.value}(unstakeDelay);
    }

    /**
     * @dev Unlock stake from the entry point
     */
    function unlockStake() public onlyOwner {
        entryPoint().unlockStake();
    }

    /**
     * @dev Withdraw stake from the entry point
     * @param withdrawAddress The address to withdraw to
     */
    function withdrawStake(address payable withdrawAddress) public onlyOwner {
        entryPoint().withdrawStake(withdrawAddress);
    }

    /**
     * @dev Transfer ownership to a new owner
     * @param newOwner The new owner address
     */
    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Invalid new owner");
        owner = newOwner;
    }

    /**
     * @dev Internal function to make calls
     * @param target The target address
     * @param value The amount of ETH to send
     * @param data The function call data
     */
    function _call(address target, uint256 value, bytes memory data) internal {
        (bool success, bytes memory result) = target.call{value: value}(data);
        if (!success) {
            assembly {
                revert(add(result, 32), mload(result))
            }
        }
    }



    /**
     * @dev Receive function to accept ETH
     */
    receive() external payable {}
}

/**
 * @title IEntryPoint
 * @dev Interface for the EntryPoint contract
 */
interface IEntryPoint {
    struct UserOperation {
        address sender;
        uint256 nonce;
        bytes initCode;
        bytes callData;
        uint256 callGasLimit;
        uint256 verificationGasLimit;
        uint256 preVerificationGas;
        uint256 maxFeePerGas;
        uint256 maxPriorityFeePerGas;
        bytes paymasterAndData;
        bytes signature;
    }

    function handleOps(UserOperation[] calldata ops, address payable beneficiary) external;
    function simulateValidation(UserOperation calldata userOp) external;
    function depositTo(address account) external payable;
    function withdrawTo(address payable withdrawAddress, uint256 amount) external;
    function addStake(uint256 unstakeDelay) external payable;
    function unlockStake() external;
    function withdrawStake(address payable withdrawAddress) external;
}

